<div class="page-head"><div><p class="eyebrow">Administration</p><h1>Category Management</h1><p>Keep your product catalogue organized.</p></div></div><section class="panel"><div class="panel-head"><h2><?=$edit?'Edit Category':'Add Category'?></h2></div><form method="post" data-validate-form><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=e($edit['id']??0)?>"><div class="form-grid"><div class="field"><label>Category Name</label><input name="name" value="<?=e($edit['name']??'')?>" placeholder="e.g. Electronics" required maxlength="100"></div></div><div class="form-actions"><button class="btn"><?=$edit?'✓ Update Category':'＋ Add Category'?></button><?php if($edit):?><a class="btn gray" href="categories.php">Cancel</a><?php endif;?></div></form></section><br><section class="panel"><div class="panel-head"><div><h2>Categories</h2><span class="panel-sub"><?=count($cs)?> categories</span></div></div><div class="table-wrap"><table class="table"><tr><th>Category</th><th>Products</th><th>Actions</th></tr><?php foreach($cs as $c):?><tr><td><b><?=e($c['name'])?></b></td><td><?=e($c['product_count'])?></td><td class="actions"><a class="btn small" href="categories.php?edit=<?=$c['id']?>">✎ Edit</a><form method="post" class="inline-form" onsubmit="return confirmDelete('Delete this category? Products will become uncategorized.')"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="delete_id" value="<?=$c['id']?>"><button class="btn small danger" type="submit">Delete</button></form></td></tr><?php endforeach;?></table></div></section><?php require __DIR__.'/../../../includes/footer.php'; ?>
